#include <iostream>
using namespace std;

int mp[510][510];

int main() {
    int n, m, q;
    cin >> n >> m >> q;
    for (int i = 0; i < q; ++i) {
        int x, y;
        cin >> x >> y;
        mp[x-1][y-1] = -1;
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (mp[i][j] == -1) {
                cout << '*' << ' ';
                continue;
            }
            for (int di = -1; di <= 1; ++di) {
                for (int dj = -1; dj <= 1; ++dj) {
                    if (i + di < 0 || i + di >= n || j + dj < 0 || j + dj >= m)
                        continue;
                    if (mp[i+di][j+dj] == -1)
                        mp[i][j] += 1;
                }
            }
            cout << mp[i][j] << ' ';
        }
        cout << '\n';
    }
    return 0;
}

#include <iostream>
using namespace std;

struct Human {
    int id;
    int w;
    double h;
} humans[1010];

void bubble_sort(int n) {
    for (int i = 0; i < n; ++i) {
        for (int j = 1; j < n - i; ++j) {
            double bmi1 = (double)humans[j-1].w / humans[j-1].h / humans[j-1].h;
            double bmi2 = (double)humans[j].w / humans[j].h / humans[j].h;
            if (bmi1 < bmi2)
                swap(humans[j - 1], humans[j]);
        }
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        humans[i].id = i + 1;
    for (int i = 0; i < n; ++i)
        cin >> humans[i].w;
    for (int i = 0; i < n; ++i)
        cin >> humans[i].h;
    bubble_sort(n);
    for (int i = 0; i < n; ++i)
        cout << humans[i].id << ' ';
    cout << endl;
    return 0;
}
